// IT Essentials – Deel II: Hardwarecomponenten – 1: Computerarchitectuur
// v = vraag, a = antwoord, o = onderwerp (bovenaan de kaart), uitleg = extra uitleg onder het antwoord
// img = tekening op de voorkant (map afbeeldingen/), imgAntwoord = tekening op de achterkant (optioneel)

const kaarten_IT_deel2_les1 = [
  // ===== Inhoud =====
  { v: "Wat beschrijft computerarchitectuur?", a: "Welke hoofdonderdelen een computer heeft en hoe ze samenwerken.", o: "Inhoud",
    uitleg: "Het gaat dus niet over één onderdeel apart, maar over het geheel. Vergelijk het met de architectuur van een huis: niet hoe een baksteen gemaakt is, maar welke kamers er zijn en hoe ze met elkaar verbonden zijn. Bij een computer: wat zit erin (processor, geheugen, ...) en hoe praten die onderdelen met elkaar (bussen)." },
  { v: "Welke 5 onderdelen horen bij de von Neumann-architectuur (in de cursus)?", a: "Processor, werkgeheugen, permanent geheugen, in-/uitvoerapparaten, chipsets en bussen.", o: "Inhoud",
    uitleg: "Elk van deze onderdelen krijgt later in de cursus een eigen hoofdstuk: werkgeheugen (H5), processoren (H6), chipsets en bussen (H7), permanent geheugen (H8 en H9), poorten (H10) en in-/uitvoerapparaten (H11). Dit hoofdstuk is dus de inleiding op alles wat volgt." },
  { v: "Wat is het verband tussen het von Neumann-model en het von Neumann-knelpunt?", a: "Het knelpunt is het grote zwakke punt van het von Neumann-model.", o: "Inhoud",
    uitleg: "Het knelpunt ontstaat juist door het belangrijkste kenmerk van het model: instructies en data staan in hetzelfde geheugen en moeten dus over dezelfde verbinding (bus) naar de processor. Wat het model eenvoudig maakt, maakt het ook traag. Dat is de rode draad tussen deel 1 en deel 2 van dit hoofdstuk." },

  // ===== Von Neumann-architectuur =====
  { v: "Is het von Neumann-model vandaag nog bruikbaar?", a: "Ja. Bijna elke pc, laptop en smartphone volgt nog het basisidee.", o: "Von Neumann-architectuur",
    uitleg: "De techniek is enorm veranderd: van ruimtes vol buizen naar een chip in je broekzak. Maar het principe is na meer dan 80 jaar nog altijd hetzelfde: een processor die instructies uit het geheugen haalt en uitvoert, met invoer en uitvoer errond. Daarom begint de cursus met dit model." },
  { v: "Belangrijkste kenmerk van het von Neumann-model?", a: "Instructies en gegevens staan in hetzelfde geheugen.", o: "Von Neumann-architectuur",
    uitleg: "Instructies = het programma: wat moet er gebeuren (bv. 'tel op'). Gegevens = de data waarmee gewerkt wordt (bv. de getallen 3 en 5). Het voordeel: één geheugen volstaat en je kan makkelijk een ander programma laden. Het nadeel: alles moet over dezelfde weg naar de processor, en dat geeft het von Neumann-knelpunt." },
  { v: "Uit hoeveel hoofdonderdelen bestaat een computer volgens von Neumann?", a: "4", o: "Von Neumann-architectuur",
    uitleg: "CPU, invoer, uitvoer en geheugen. Let op het verschil: het model zelf heeft er 4, maar de cursus bespreekt er 5 (processor, werkgeheugen, permanent geheugen, randapparatuur, chipsets en bussen). In de cursus wordt het geheugen gesplitst in twee soorten, en komen de verbindingen (bussen) er apart bij." },
  { v: "Welke 4 hoofdonderdelen heeft een computer volgens von Neumann?", a: "CPU, invoer, uitvoer, geheugen.", o: "Von Neumann-architectuur",
    uitleg: "CPU = de processor die het werk doet. Invoer = apparaten die gegevens naar de computer sturen (toetsenbord, muis). Uitvoer = apparaten die resultaten naar buiten brengen (scherm, printer). Geheugen = de plaats waar instructies en gegevens bewaard worden, opgesplitst in vluchtig en niet-vluchtig." },
  { v: "Waar staat CPU voor?", a: "Central Processing Unit.", o: "Von Neumann-architectuur",
    uitleg: "Letterlijk: centrale verwerkingseenheid. 'Centraal' omdat alles erom draait, 'verwerking' omdat hij de instructies uitvoert. CPU en processor betekenen hetzelfde. Verwar het niet met de GPU (Graphics Processing Unit), de grafische processor." },
  { v: "In welke 2 soorten wordt geheugen opgedeeld?", a: "Vluchtig (volatile) en niet-vluchtig (non-volatile).", o: "Von Neumann-architectuur",
    uitleg: "Vluchtig: de inhoud verdwijnt als de stroom wegvalt. Dat is het werkgeheugen (RAM), snel maar tijdelijk. Niet-vluchtig: de inhoud blijft bewaard zonder stroom. Dat is het permanente geheugen, zoals een harde schijf of SSD, trager maar blijvend. Een computer heeft ze allebei nodig." },
  { v: "Voorbeeld van vluchtig en niet-vluchtig geheugen?", a: "Vluchtig: RAM.\nNiet-vluchtig: harde schijf.", o: "Von Neumann-architectuur",
    uitleg: "Andere voorbeelden van niet-vluchtig geheugen zijn een SSD, een USB-stick en een SD-kaart in je camera. Die kan je uit een toestel halen en je bestanden staan er nog op. Het RAM-geheugen daarentegen is leeg zodra je de computer uitzet." },
  { v: "Wat doet de Control Unit?", a: "Stuurt de uitvoering aan.", o: "Von Neumann-architectuur",
    uitleg: "Ze haalt de volgende instructie uit het geheugen, zoekt uit wat die betekent (ontcijferen) en geeft de andere onderdelen de juiste opdrachten, bijvoorbeeld 'ALU, tel deze twee getallen op'. Ze rekent zelf niets uit, maar regelt de hele volgorde. Zonder Control Unit weet de ALU niet wat hij moet doen." },
  { v: "Wat doet de ALU?", a: "Berekeningen en logische bewerkingen.", o: "Von Neumann-architectuur",
    uitleg: "Rekenkundige bewerkingen: optellen, aftrekken, vermenigvuldigen, ... Logische bewerkingen: AND, OR, NOT, XOR en vergelijken (is A groter dan B?). Binnenin is de ALU opgebouwd uit logische poorten en optellers, precies wat je in Deel I geleerd hebt. Daar komt de theorie van Deel I samen met de hardware." },
  { v: "Waar staat ALU voor?", a: "Arithmetic/Logic Unit.", o: "Von Neumann-architectuur",
    uitleg: "Arithmetic = rekenkundig (zoals in 'aritmetica'). Logic = logisch. Unit = eenheid. In het Nederlands dus: de rekenkundige en logische eenheid. De naam zegt precies wat ze doet." },
  { v: "Waarom pijlen in beide richtingen tussen CPU en geheugen?", a: "De CPU leest uit het geheugen én schrijft ernaar terug.", o: "Von Neumann-architectuur",
    uitleg: "Lezen: de CPU haalt instructies en gegevens uit het geheugen. Schrijven: de CPU bewaart de resultaten van zijn berekeningen terug in het geheugen. Bij invoer en uitvoer staat telkens maar één pijl: invoer gaat alleen naar de CPU, uitvoer komt alleen van de CPU." },
  { v: "Voorbeeld invoer- en uitvoerapparaat?", a: "Invoer: toetsenbord, muis.\nUitvoer: scherm, printer.", o: "Von Neumann-architectuur",
    uitleg: "Andere invoer: scanner, microfoon, webcam. Andere uitvoer: luidsprekers, koptelefoon, projector. Sommige toestellen doen beide, zoals een touchscreen (je tikt erop én het toont beeld) of een headset met microfoon." },
  { v: "🖼️ Benoem de onderdelen 1 tot 6 in dit schema van de von Neumann-architectuur.", a: "1. Central Processing Unit (CPU, processor)\n2. Control Unit (besturingseenheid)\n3. Arithmetic/Logic Unit (ALU, rekeneenheid)\n4. Memory Unit (geheugen)\n5. Input Device (invoer)\n6. Output Device (uitvoer)", o: "Von Neumann-architectuur", img: "afbeeldingen/l1_s04_vonneumann_vraag.jpg", imgAntwoord: "afbeeldingen/l1_s04_vonneumann.jpg",
    uitleg: "Dit zijn de 4 hoofdonderdelen van von Neumann: CPU, invoer, uitvoer en geheugen. In de CPU zitten nog 2 delen: de Control Unit stuurt alles aan (het 'brein in het brein') en de ALU doet het rekenwerk en de logische bewerkingen. Ezelsbruggetje: lees het schema van links naar rechts zoals de gegevens stromen: invoer → verwerking in de CPU (met hulp van het geheugen) → uitvoer." },
  { v: "🖼️ Wat betekenen de twee pijlen tussen de CPU en de Memory Unit in dit schema?", a: "Gegevens gaan in beide richtingen: de CPU haalt instructies en data uit het geheugen en schrijft resultaten terug naar het geheugen.", o: "Von Neumann-architectuur", img: "afbeeldingen/l1_s04_vonneumann.jpg",
    uitleg: "Bij invoer en uitvoer is er maar één pijl (invoer → CPU, CPU → uitvoer), maar met het geheugen praat de CPU de hele tijd heen en weer. In het von Neumann-model gaan instructies én data over dezelfde verbinding (bus). Precies hier zit het von Neumann-knelpunt (slide 10): die ene verbinding bepaalt mee hoe snel de computer kan werken." },
  { v: "🖼️ Waarom staan Input Device en Output Device buiten het grote blok in dit schema?", a: "Het zijn randapparaten: ze horen niet bij de processor of het geheugen, maar worden via poorten aangesloten.", o: "Von Neumann-architectuur", img: "afbeeldingen/l1_s04_vonneumann.jpg",
    uitleg: "Het grote groene blok is de eigenlijke computer (CPU + geheugen). Toetsenbord, muis, printer en scherm hangen daarbuiten en worden aangesloten via poorten (slide 8). De pijlen tonen de richting: invoer brengt gegevens naar de CPU, uitvoer krijgt gegevens van de CPU." },
  { v: "Tot welke categorie binnen de von Neumann-architectuur hoort een USB-stick?\na) Input\nb) Output\nc) CPU/processor\nd) Bussen/chipsets\ne) Volatile memory (niet-bestendig geheugen)\nf) Non-volatile memory (bestendig geheugen)", a: "f) Non-volatile memory (bestendig geheugen).", o: "Von Neumann-architectuur",
    uitleg: "Een USB-stick bewaart zijn gegevens ook zonder stroom, dus het is bestendig geheugen, net zoals een harde schijf, SSD, cd of dvd. Valkuil: je steekt de stick in een poort, net als een toetsenbord. Maar de vraag is wat het toestel doet, en dat is gegevens bewaren. Het werkgeheugen (RAM) is wel volatile: alles weg bij stroomuitval." },
  { v: "Duid per onderdeel de juiste von Neumann-categorie aan (Input, Output, CPU, Bussen/chipsets, Volatile memory of Non-volatile memory):\n• webcam\n• beamer\n• SSD\n• DDR5-geheugenlatje\n• cd-rom\n• chipset op het moederbord\n• microfoon\n• Control Unit", a: "• webcam → Input\n• beamer → Output\n• SSD → Non-volatile memory\n• DDR5-geheugenlatje → Volatile memory\n• cd-rom → Non-volatile memory\n• chipset → Bussen/chipsets\n• microfoon → Input\n• Control Unit → CPU", o: "Von Neumann-architectuur",
    uitleg: "Stel jezelf telkens de vraag: brengt het gegevens naar binnen (input), stuurt het gegevens naar buiten (output), bewaart het gegevens (geheugen: blijven ze bewaard zonder stroom of niet?), verbindt het onderdelen (bussen/chipsets) of verwerkt het (CPU)? De Control Unit is een onderdeel ván de CPU." },
  { v: "De ALU in de processor…\na) stuurt de andere componenten in de processor aan om alles in goede banen te leiden.\nb) voert rekenkundige bewerkingen (optellen, …) en logische bewerkingen (AND, OR, NOT) uit.\nc) controleert het RAM-geheugen op fouten.\nd) is de tijdelijke opslag voor gegevens en resultaten in de processor.", a: "b) De ALU (Arithmetic/Logic Unit) voert rekenkundige en logische bewerkingen uit.", o: "Von Neumann-architectuur",
    uitleg: "a) is de Control Unit: die stuurt alles aan. Die twee worden op het examen vaak met elkaar verwisseld! c) bestaat niet als onderdeel van de processor; foutencontrole van geheugen is pariteit of ECC (hoofdstuk 2). d) zijn de registers." },
  { v: "Juist of fout? In de von Neumann-architectuur hebben instructies en data elk een eigen bus.", a: "FOUT", o: "Von Neumann-architectuur",
    uitleg: "Bij von Neumann delen instructies en data dezelfde verbinding (bus) tussen CPU en geheugen. Daardoor ontstaat het von Neumann-knelpunt." },
  { v: "Juist of fout? Een computer volgens von Neumann bestaat uit 4 hoofdonderdelen: CPU, invoer, uitvoer en geheugen.", a: "JUIST", o: "Von Neumann-architectuur",
    uitleg: "In de CPU zitten nog de Control Unit en de ALU. Het geheugen wordt verder opgesplitst in vluchtig (volatile) en niet-vluchtig (non-volatile)." },
  { v: "Juist of fout? Het werkgeheugen is bestendig geheugen.", a: "FOUT", o: "Von Neumann-architectuur",
    uitleg: "Werkgeheugen is vluchtig (volatile): alle informatie is weg bij stroomuitval. Permanent geheugen, zoals een harde schijf, is bestendig." },
  { v: "Juist of fout? De Control Unit en de ALU zitten allebei in de CPU.", a: "JUIST", o: "Von Neumann-architectuur",
    uitleg: "De Control Unit stuurt alles aan ('brein in het brein'), de ALU doet het reken- en logische werk. Samen vormen ze de kern van de processor." },

  // ===== Processor =====
  { v: "Wat is de processor?", a: "De meest centrale component van een computersysteem.", o: "Processor",
    uitleg: "In de von Neumann-architectuur staat de processor letterlijk in het midden: invoer komt naar hem toe, uitvoer komt van hem, en hij praat voortdurend met het geheugen. Alle andere onderdelen zijn er eigenlijk om de processor van werk te voorzien of de resultaten op te vangen." },
  { v: "Wat doet de processor?", a: "Uiteindelijk al het werk.", o: "Processor",
    uitleg: "Wanneer je een programma uitvoert, verricht de processor het meeste werk: rekenen, vergelijken, beslissen wat er daarna moet gebeuren. Het geheugen bewaart alleen, de randapparatuur brengt alleen in en uit. Daarom bepaalt de processor voor een groot deel hoe snel je computer aanvoelt." },
  { v: "Wat is een programma voor de processor?", a: "Een lange reeks instructies.", o: "Processor",
    uitleg: "Elke instructie is een heel kleine opdracht, zoals 'haal dit getal uit het geheugen', 'tel deze twee getallen op' of 'spring naar instructie 120 als het resultaat nul is'. Een programma als een browser bestaat uit miljoenen van zulke instructies. De processor begrijpt alleen deze kleine opdrachten, geen hele zinnen." },
  { v: "Hoe voert de processor een volledig programma uit?", a: "Door opeenvolgende instructies te verwerken.", o: "Processor",
    uitleg: "Eén voor één, na elkaar, miljarden keren per seconde. Door een hele reeks kleine opdrachten snel na elkaar uit te voeren, ontstaat iets groots: een webpagina die laadt, een game die draait. Het is zoals een film: losse beelden die snel na elkaar komen, worden beweging." },
  { v: "In welke 3 stappen wordt een instructie behandeld?", a: "Ophalen, ontcijferen, uitvoeren.", o: "Processor",
    uitleg: "1. Ophalen: de instructie uit het geheugen halen. 2. Ontcijferen: uitzoeken wat de instructie betekent en wat ervoor nodig is. 3. Uitvoeren: de bewerking echt doen, vaak in de ALU. Daarna begint het opnieuw met de volgende instructie. Deze herhaling heet de instructiecyclus." },
  { v: "Wat betekenen fetch, decode en execute?", a: "Fetch = ophalen\nDecode = ontcijferen\nExecute = uitvoeren", o: "Processor",
    uitleg: "Dit zijn de Engelse namen van de drie stappen van de instructiecyclus. Je komt ze vaak tegen in Engelstalige bronnen en in het hoofdstuk Processoren. Ezelsbruggetje: denk aan een ober: de bestelling opnemen (fetch), lezen wat er gevraagd wordt (decode), het gerecht brengen (execute)." },
  { v: "🖼️ Welk onderdeel zie je op deze foto, en wat doet het?", a: "De processor (CPU), hier een Intel Core i7: het meest centrale onderdeel van de computer, dat uiteindelijk al het werk doet.", o: "Processor", img: "afbeeldingen/l1_s05_processor.jpg",
    uitleg: "Wat je ziet is vooral de metalen kap (heatspreader): die verdeelt de warmte naar de koeler. Het eigenlijke stukje silicium (de die) zit daaronder. Aan de onderkant zitten honderden contactpunten die in de socket op het moederbord passen. In hoofdstuk 3 (Processoren) zie je foto's van die die." },

  // ===== Werkgeheugen =====
  { v: "Waarom is er een werkgeheugen nodig?", a: "Het geheugen van de processor zelf is veel te klein.", o: "Werkgeheugen",
    uitleg: "De processor heeft wel een eigen geheugen (de registers), maar daar passen maar een handvol getallen in. Een modern programma met al zijn data is vele megabytes groot. Daarom voorziet elke computer een apart werkgeheugen, waarin het programma en zijn data tijdens het werken klaarliggen." },
  { v: "Hoe heet het eigen geheugen van de processor?", a: "Registers.", o: "Werkgeheugen",
    uitleg: "De cursus zet 'geheugen' tussen aanhalingstekens, omdat registers eigenlijk maar een paar tientallen plaatsjes zijn. Ze zitten in de processor zelf en zijn daardoor razendsnel: minder dan 1 nanoseconde. Elke berekening gebeurt met getallen die op dat moment in de registers staan." },
  { v: "Wat zijn registers?", a: "De kleinste en snelste geheugenplaatsen, in de processor zelf.", o: "Werkgeheugen",
    uitleg: "Vergelijk met een kladblaadje naast je rekenmachine: je schrijft er de getallen op waar je nu mee bezig bent. Wil de ALU twee getallen optellen, dan staan die eerst in registers, en het resultaat komt ook weer in een register. Ze staan helemaal bovenaan de geheugenhiërarchie: het snelst, maar het kleinst." },
  { v: "Waarom kan de processor niet alleen met zijn registers werken?", a: "Ze zijn veel te klein voor moderne software.", o: "Werkgeheugen",
    uitleg: "Registers kunnen samen hooguit enkele kilobytes bevatten. Een browser of een game heeft honderden megabytes of zelfs gigabytes nodig. Je kan registers ook niet zomaar groter maken: dan worden ze trager en duurder, en verliezen ze hun voordeel. Daarom is er een groter werkgeheugen ernaast." },
  { v: "Waarvoor dient het werkgeheugen?", a: "Programma's en data inladen voor uitvoering.", o: "Werkgeheugen",
    uitleg: "Als je een programma opent, wordt het van de schijf naar het werkgeheugen gekopieerd. Ook de bestanden waarmee je werkt (bv. een Word-document) worden daar ingeladen. Zolang het programma openstaat, haalt de processor zijn instructies en gegevens uit het werkgeheugen. Daarom duurt het opstarten van een programma even: het moet eerst ingeladen worden." },
  { v: "Waarom laad je programma's van de schijf in het werkgeheugen?", a: "De processor kan veel sneller aan het werkgeheugen dan aan de schijf.", o: "Werkgeheugen",
    uitleg: "Werkgeheugen antwoordt in ongeveer 50 tot 100 nanoseconden, een SSD in ongeveer 100.000 nanoseconden en een harde schijf in miljoenen nanoseconden. Rechtstreeks van de schijf werken zou de processor dus voortdurend laten wachten. Daarom kopieer je alles één keer naar het snelle werkgeheugen.\n\nAchtergrond (wordt niet gevraagd): Waarom moet werkgeheugen uiterst snel zijn? Zodat de processor niet lang moet wachten op instructies. De instructies van het programma staan in het werkgeheugen. Bij elke instructie moet de processor iets uit het geheugen halen. Is het werkgeheugen traag, dan staat de processor het grootste deel van de tijd stil. Dit is precies het von Neumann-knelpunt: de verbinding met het geheugen remt alles af." },
  { v: "Is werkgeheugen vluchtig of niet-vluchtig?", a: "Vluchtig (volatile).", o: "Werkgeheugen",
    uitleg: "Vluchtig betekent dat de inhoud verloren gaat als de stroom wegvalt. Bij het opstarten is het werkgeheugen dus altijd leeg, en moet alles opnieuw van de schijf ingeladen worden. Dat is een van de redenen waarom een computer even nodig heeft om op te starten.\n\nAchtergrond (wordt niet gevraagd): Waarom is werkgeheugen vluchtig? Het moet zo snel zijn dat geheugen dat zonder stroom bewaart niet kan. Er bestaan geen fysieke geheugens die tegelijk zo snel zijn als RAM én hun gegevens zonder stroom bewaren. RAM bewaart elke bit als een klein elektrisch ladinkje, dat heel snel te lezen en te veranderen is, maar wegloopt zonder stroom. Men kiest dus bewust voor snelheid en neemt het vluchtige erbij." },
  { v: "Gangbare naam van het werkgeheugen?", a: "RAM.", o: "Werkgeheugen",
    uitleg: "Als iemand zegt 'mijn laptop heeft 16 GB RAM', bedoelt hij het werkgeheugen. Hoe meer RAM, hoe meer programma's en tabbladen je tegelijk kan openhouden zonder dat de computer traag wordt. Vandaag is 8 tot 64 GB gangbaar." },
  { v: "Waar staat RAM voor?", a: "Random Access Memory.", o: "Werkgeheugen",
    uitleg: "Random access = willekeurige toegang: elke plaats in het geheugen kan rechtstreeks en even snel bereikt worden, in om het even welke volgorde. Het tegenovergestelde is sequentiële toegang, zoals bij een cassettebandje: om bij een liedje achteraan te komen, moet je eerst alles ervoor doorspoelen." },
  { v: "🖼️ Welk onderdeel zie je op deze foto, en waarom heeft een computer het nodig?", a: "Een werkgeheugenmodule (RAM-latje). Het geheugen van de processor zelf is veel te klein, dus programma's en data worden in het werkgeheugen ingeladen. Het is vluchtig.", o: "Werkgeheugen", img: "afbeeldingen/l1_s06_werkgeheugen.jpg",
    uitleg: "De zwarte blokjes zijn de geheugenchips. De goudkleurige contacten onderaan gaan in een sleuf (slot) op het moederbord. Vluchtig (volatile) betekent dat alles weg is als de stroom uitvalt. In hoofdstuk 2 leer je dat zo'n module een DIMM heet, en dat de inkeping tussen de contacten per DDR-generatie op een andere plaats zit." },
  { v: "Waarom heeft een computer werkgeheugen nodig?\na) Om programma's en data permanent te bewaren.\nb) Omdat het geheugen van de processor zelf veel te klein is om programma's en data in te laden.\nc) Om de verbinding tussen de processor en de randapparaten te maken.\nd) Om de processor te koelen.", a: "b) Het geheugen van de processor is veel te klein, dus programma's en data worden in het werkgeheugen ingeladen.", o: "Werkgeheugen",
    uitleg: "a) is fout: werkgeheugen is vluchtig, dus niet permanent. Daarvoor dient het permanent geheugen (harde schijf, SSD). c) is de taak van chipsets en bussen.\n\nAchtergrond (wordt niet gevraagd): Wat gaat voor bij werkgeheugen: snelheid of bewaren zonder stroom? Snelheid. Het blijvend bewaren laat men over aan het permanente geheugen (harde schijf, SSD). Zo heeft elk soort geheugen zijn eigen taak: het werkgeheugen is snel voor het werk van nu, het permanente geheugen is blijvend voor later. Daarom moet je je werk opslaan." },

  // ===== Permanent geheugen =====
  { v: "Wat gebeurt er met het werkgeheugen bij stroomuitval?", a: "Alle informatie is weg.", o: "Permanent geheugen",
    uitleg: "Omdat het werkgeheugen vluchtig (volatile) is. Alles wat alleen in het werkgeheugen stond, is in één klap verdwenen: open documenten die niet opgeslagen waren, je open tabbladen, de toestand van programma's. Daarom slaan veel programma's vandaag automatisch op." },
  { v: "Verschil permanent geheugen vs werkgeheugen?", a: "Permanent verliest niets bij stroomuitval, werkgeheugen wel.", o: "Permanent geheugen",
    uitleg: "Daartegenover staat dat permanent geheugen veel trager is dan werkgeheugen. Je hebt ze dus allebei nodig: het werkgeheugen om snel mee te werken, het permanente geheugen om alles blijvend te bewaren. Programma's staan permanent op de schijf en worden bij het openen naar het werkgeheugen gekopieerd." },
  { v: "Wat is sneller: werkgeheugen of permanent geheugen?", a: "Werkgeheugen.", o: "Permanent geheugen",
    uitleg: "Algemene regel: hoe sneller het geheugen, hoe kleiner en duurder per GB. Van snel naar traag: registers > cache > werkgeheugen (RAM) > SSD > harde schijf. Dit heet de geheugenhiërarchie en komt terug in het hoofdstuk Werkgeheugen." },
  { v: "Waarom is er permanent geheugen nodig?", a: "Om gegevens te bewaren als de stroom uitgaat.", o: "Permanent geheugen",
    uitleg: "De cursus stelt de vraag: wat als we de stroom van de computer uitzetten? Zonder permanent geheugen zou je bij elke herstart alles kwijt zijn: het besturingssysteem, je programma's, je bestanden. Het permanente geheugen is dus de plek waar alles 'woont' als de computer uit staat." },
  { v: "2 voorbeelden van permanent geheugen?", a: "Harde schijf en SSD.", o: "Permanent geheugen",
    uitleg: "Een harde schijf (HDD) werkt met draaiende magnetische platen en een leeskop, zoals een platenspeler: goedkoop en groot, maar traag. Een SSD gebruikt flash-geheugenchips zonder bewegende delen: veel sneller en schokbestendig, maar duurder per GB. In moderne laptops zit bijna altijd een SSD." },
  { v: "Andere naam voor permanent geheugen in de cursus?", a: "Bestendig geheugen.", o: "Permanent geheugen",
    uitleg: "Let op dit woord: het kan op het examen staan in plaats van 'permanent'. Bestendig, permanent en niet-vluchtig (non-volatile) betekenen allemaal hetzelfde: de gegevens blijven bewaard zonder stroom." },
  { v: "Wat betekent 'bestendig'?", a: "Blijvend: gegevens blijven bewaard zonder stroom.", o: "Permanent geheugen",
    uitleg: "Het is het tegenovergestelde van vluchtig. In gewone taal zeg je bijvoorbeeld 'bestendig weer': weer dat lang hetzelfde blijft. Bij geheugen: inhoud die blijft, ook als de computer uit staat." },
  { v: "Waarom verlies je niet-opgeslagen werk bij een stroompanne?", a: "Het staat alleen in het vluchtige werkgeheugen.", o: "Permanent geheugen",
    uitleg: "Terwijl je typt, staat je document alleen in het werkgeheugen. Pas als je op 'Opslaan' klikt, wordt het naar het permanente geheugen (de schijf) geschreven. Valt de stroom uit voor je opslaat, dan verdwijnt het samen met de rest van het werkgeheugen. Een laptop heeft hier minder last van dankzij zijn batterij." },
  { v: "🖼️ Welk onderdeel zie je op deze foto, en wat voor geheugen is het?", a: "Een harde schijf: permanent (niet-vluchtig) geheugen. De informatie blijft bewaard als de stroom uitvalt.", o: "Permanent geheugen", img: "afbeeldingen/l1_s07_hardeschijf.jpg",
    uitleg: "Dat is het grote verschil met het werkgeheugen, dat alles verliest bij stroomuitval. Binnenin draaien magnetische platen. In hoofdstuk 2 heet dat cyclische toegang: de kop moet wachten tot het juiste stuk voorbij draait. Daarom is een harde schijf veel trager dan werkgeheugen (5 tot 10 ms tegenover 50 tot 100 ns). Vandaag gebruikt men vaak een SSD (flashgeheugen) als permanent geheugen." },

  // ===== In- en uitvoerapparaten =====
  { v: "Andere naam voor in- en uitvoerapparaten?", a: "Randapparatuur.", o: "In- en uitvoerapparaten",
    uitleg: "In het Engels: peripherals of I/O devices (Input/Output). Het woord 'randapparatuur' omvat alles wat je aan de computer koppelt om er gegevens in te krijgen of uit te halen.\n\nAchtergrond (wordt niet gevraagd): Waarom heet het 'randapparatuur'? Het staat 'aan de rand', rond processor en geheugen. Processor en geheugen vormen de kern van de computer. De randapparatuur zit daar als het ware rond en vormt de verbinding met de buitenwereld: met jou (toetsenbord, scherm) en met andere toestellen (printer, netwerk). Zonder kern doet de rand niets, en zonder rand kan je de kern niet gebruiken." },
  { v: "Hoe wordt randapparatuur aangesloten?", a: "Via poorten.", o: "In- en uitvoerapparaten",
    uitleg: "Een poort is een aansluiting op de computer waar je een kabel of apparaat in steekt. Elke soort poort heeft een eigen vorm en eigen regels voor hoe de gegevens doorgestuurd worden. Draadloze verbindingen zoals bluetooth en wifi werken als een soort 'onzichtbare poort'.\n\nAchtergrond (wordt niet gevraagd): 3 voorbeelden van poorten? USB, HDMI, netwerkpoort. USB: voor muis, toetsenbord, USB-stick, printer, ... (de meest gebruikte poort). HDMI: voor een scherm of tv, stuurt beeld en geluid. Netwerkpoort (RJ45): voor een internetkabel. Op nieuwere laptops is USB-C vaak de alles-in-één-poort." },
  { v: "Voorbeelden van randapparatuur op de slide?", a: "Keyboard, muis, printer, monitor.", o: "In- en uitvoerapparaten",
    uitleg: "Op de slide staan foto's van een draadloos toetsenbord met muis (invoer), een Canon-printer en een Dell-monitor (uitvoer). Samen tonen ze de twee richtingen: gegevens naar de computer toe en van de computer weg." },
  { v: "Invoer vs uitvoer?", a: "Invoer gaat naar de computer.\nUitvoer komt van de computer.", o: "In- en uitvoerapparaten",
    uitleg: "Denk vanuit de computer: invoer (input) komt binnen, uitvoer (output) gaat naar buiten. Invoer: toetsenbord, muis, scanner, microfoon, webcam. Uitvoer: monitor, printer, luidsprekers. Sommige apparaten doen beide, zoals een touchscreen of een netwerkkaart.\n\nAchtergrond (wordt niet gevraagd): Waarvoor dienen in- en uitvoerapparaten? Om met de computer te interageren (signalen uitwisselen). Zonder randapparatuur kan je de computer niets vertellen, en kan hij jou niets tonen. Een computer zonder toetsenbord, muis en scherm rekent misschien wel, maar je hebt er niets aan. Randapparatuur is dus de brug tussen mens en machine." },
  { v: "Printer: invoer of uitvoer?", a: "Uitvoer.", o: "In- en uitvoerapparaten",
    uitleg: "De gegevens gaan van de computer naar het papier. De computer stuurt het document, de printer zet het om naar iets wat je kan vastnemen. Let op: een multifunctionele printer met scanner doet beide." },
  { v: "Scanner: invoer of uitvoer?", a: "Invoer.", o: "In- en uitvoerapparaten",
    uitleg: "De gegevens gaan van het papier naar de computer. Een scanner is dus het omgekeerde van een printer: hij zet iets fysieks om naar digitale gegevens. Ook een webcam en een microfoon zijn invoer: ze vangen beeld of geluid op en sturen het naar de computer." },
  { v: "🖼️ Hoe noem je deze toestellen samen? Welke zijn invoer en welke uitvoer?", a: "Randapparatuur (in- en uitvoerapparaten), aangesloten via poorten.\nInvoer: toetsenbord en muis.\nUitvoer: printer en beeldscherm.", o: "In- en uitvoerapparaten", img: "afbeeldingen/l1_s08_randapparatuur.jpg",
    uitleg: "Invoer brengt gegevens naar de computer toe, uitvoer brengt gegevens van de computer naar buiten. In het von Neumann-schema zijn dat de blokken Input Device en Output Device. Sommige toestellen doen allebei, bijvoorbeeld een aanraakscherm of een printer met scanner." },

  // ===== Chipsets en bussen =====
  { v: "Wat is de rol van chipsets en bussen?", a: "Alle componenten met elkaar verbinden.", o: "Chipsets en bussen",
    uitleg: "Ze zorgen ervoor dat processor, geheugen en randapparatuur met elkaar kunnen communiceren. Zonder bussen en chipset zijn het losse onderdelen die niets van elkaar weten. Je kan ze vergelijken met het wegennet en de verkeerslichten van een stad." },
  { v: "Hoe belangrijk zijn chipsets en bussen volgens de slide?", a: "Een niet te onderschatten component!", o: "Chipsets en bussen",
    uitleg: "De slide zet er zelfs een uitroepteken achter. Mensen kijken bij een computer vooral naar de processor en het geheugen, maar vergeten vaak de verbindingen ertussen. Toch kunnen die de hele computer vertragen.\n\nAchtergrond (wordt niet gevraagd): Waarom zijn chipsets en bussen niet te onderschatten? Bij trage verbindingen moet zelfs de snelste processor wachten. Een supersnelle processor met een trage bus is als een sportwagen in de file: de motor kan 250 km/u, maar je rijdt 20. Dit hangt rechtstreeks samen met het von Neumann-knelpunt, waar de bus tussen processor en geheugen de snelheid van de hele computer bepaalt." },
  { v: "Wat noemt de cursus de 'lijm' van het systeem?", a: "Bussen.", o: "Chipsets en bussen",
    uitleg: "Bussen brengen de verschillende onderdelen van het computersysteem samen, zoals lijm losse stukken samenhoudt. Het woord 'bus' komt van het Latijnse 'omnibus' (voor allen): een gedeelde weg die door meerdere onderdelen gebruikt wordt, net zoals een bus veel passagiers vervoert." },
  { v: "Wat is een bus?", a: "Een stel verbindingen waarover gegevens en signalen tussen onderdelen gaan.", o: "Chipsets en bussen",
    uitleg: "Fysiek zijn het koperen baantjes op het moederbord of draadjes in een chip. Vergelijk met een snelweg: hoe meer rijstroken (de breedte van de bus) en hoe hoger de toegelaten snelheid, hoe meer data er per seconde door kan. Die hoeveelheid noemen we de bandbreedte." },
  { v: "Waarom zijn er naast bussen extra chips (chipset) nodig?", a: "Een bus is alleen maar een verbinding (een bundel draadjes). Er is ook iets nodig dat de verschillende bussen met elkaar verbindt, vertaalt tussen trage en snelle onderdelen, en beslist wie wanneer gegevens mag doorsturen. Dat doet de chipset.", o: "Chipsets en bussen",
    uitleg: "Zie de bus als een weg en de chipset als een knooppunt met verkeerslichten. 1) Verbinden: elk onderdeel hangt aan zijn eigen soort bus (het geheugen, de grafische kaart via PCIe, de harde schijf via SATA, USB, …). Die bussen komen samen in de chipset. 2) Vertalen: de processor is razendsnel, een USB-stick is traag, en elke bus 'spreekt' een andere taal. De chipset zet de gegevens om van de ene bus naar de andere. 3) Regelen: als meerdere onderdelen tegelijk iets willen sturen, bepaalt de chipset wie eerst mag. Anders sturen ze door elkaar en gaan er gegevens verloren. Voorbeeld uit het schema op de slide: je slaat een bestand op. De gegevens gaan van de processor naar de X58-chip, via DMI naar de ICH10-chip, en die stuurt ze via SATA naar de harde schijf. X58 en ICH10 zijn samen de chipset." },
  { v: "Wat is de chipset?", a: "Chips op het moederbord die het dataverkeer tussen processor, geheugen en randapparatuur regelen.", o: "Chipsets en bussen",
    uitleg: "Het moederbord is de grote printplaat waarop alle onderdelen worden aangesloten. De chipset bepaalt mee wat het moederbord kan: hoeveel USB-poorten, welke soort geheugen, hoeveel SATA-aansluitingen, ... Bij het kopen van een moederbord kijk je daarom ook naar de chipset." },
  { v: "🖼️ Wat toont dit schema?", a: "Een chipset: hoe alle onderdelen (processor, werkgeheugen, grafische kaart, USB, SATA, netwerk, audio, BIOS, …) via chips en bussen met elkaar verbonden zijn.", o: "Chipsets en bussen", img: "afbeeldingen/l1_s09_chipset.jpg",
    uitleg: "Het voorbeeld is een Intel Core i7-systeem met de X58-chip (IOH = I/O Hub) en de ICH10-chip (I/O Controller Hub). Bij elke verbinding staat hoe snel ze is. De slide zegt dat chipsets en bussen 'niet te onderschatten' zijn: de snelste processor helpt niet als de verbindingen hem niet snel genoeg van data voorzien." },
  { v: "Wat is de functie van chipsets en bussen in een computersysteem?\na) Gegevens permanent opslaan.\nb) Alle componenten met elkaar verbinden.\nc) Berekeningen uitvoeren voor de processor.\nd) Het beeld naar het scherm sturen.", a: "b) Alle componenten met elkaar verbinden.", o: "Chipsets en bussen",
    uitleg: "De slide zegt erbij: 'niet te onderschatten component in een computersysteem'. Hoe snel de verbindingen zijn, bepaalt mee hoe snel de hele computer is (denk aan het von Neumann-knelpunt)." },

  // ===== Het von Neumann-knelpunt =====
  { v: "Wat is het probleem van von Neumann?", a: "Instructies en data delen dezelfde bus tussen CPU en geheugen.", o: "Het von Neumann-knelpunt",
    uitleg: "De slide zegt letterlijk: 'Von Neumann heeft 1 probleem'. Omdat instructies én data over dezelfde verbinding moeten, kan de processor ze niet tegelijk ophalen. Elke instructie die iets met data doet, gebruikt de bus dus meerdere keren na elkaar." },
  { v: "Wat gebeurt bij een bewerking op data uit het geheugen?", a: "Data gaat naar de CPU, resultaat weer terug: 2x over de bus.", o: "Het von Neumann-knelpunt",
    uitleg: "Voorbeeld 'tel 1 op bij het getal in het geheugen': eerst moet de instructie zelf over de bus, dan het getal van het geheugen naar de CPU, en daarna het resultaat terug naar het geheugen. Drie ritten over dezelfde bus voor één simpele optelling, en de processor wacht bij elke rit." },
  { v: "Wat bepaalt mee hoe snel een von Neumann-computer is?", a: "De grootte van de bus tussen CPU en geheugen.", o: "Het von Neumann-knelpunt",
    uitleg: "Met 'grootte' bedoelt men hoeveel data er per keer en per seconde over kan: de bandbreedte. Niet alleen de snelheid van de processor telt dus, maar ook hoe snel je hem van data kan voorzien. Dat is waarom de slide over chipsets en bussen zegt dat ze niet te onderschatten zijn." },
  { v: "Hoe heet dit probleem?", a: "Het von Neumann-knelpunt (von Neumann bottleneck).", o: "Het von Neumann-knelpunt",
    uitleg: "Ken zowel de Nederlandse als de Engelse naam, beide kunnen op het examen staan. Het knelpunt is geen fout of bug: het is een gevolg van de keuze om instructies en data in hetzelfde geheugen te zetten." },
  { v: "Het knelpunt in één zin?", a: "Processor en geheugen praten via één gedeelde verbinding.", o: "Het von Neumann-knelpunt",
    uitleg: "Volledige definitie uit de cursus: de beperking die ontstaat doordat de processor en het geheugen via één gedeelde verbinding met elkaar praten. Daardoor bepaalt die ene verbinding de snelheid van de hele computer, en niet de rekenkracht van de processor." },
  { v: "Waarom kan de CPU niet tegelijk een instructie ophalen én data lezen?", a: "Ze gebruiken dezelfde bus, dus het moet na elkaar.", o: "Het von Neumann-knelpunt",
    uitleg: "Twee dingen tegelijk over één smalle brug kan niet: eerst het ene, dan het andere. De processor kan dus niet de volgende instructie al ophalen terwijl hij nog data leest of wegschrijft. Bij de Harvard-architectuur kan dat wel, omdat instructies en data elk hun eigen bus hebben." },
  { v: "Waarom zit de processor vaak te wachten?", a: "Processoren zijn veel sneller dan geheugen.", o: "Het von Neumann-knelpunt",
    uitleg: "Een moderne processor voert een instructie uit in een fractie van een nanoseconde, terwijl werkgeheugen 50 tot 100 nanoseconden nodig heeft om te antwoorden. De processor kan dus honderden instructies uitvoeren in de tijd dat hij op één antwoord van het geheugen wacht. Dat verschil is door de jaren alleen maar groter geworden.\n\nAchtergrond (wordt niet gevraagd): Wat is een gpu? Grafische processor: veel kleine berekeningen tegelijk. GPU = Graphics Processing Unit. Een gpu heeft duizenden kleine, eenvoudige kernen, ideaal om miljoenen pixels tegelijk te berekenen. Daarom wordt hij ook veel gebruikt voor AI, die ook massa's eenvoudige berekeningen tegelijk nodig heeft. Een CPU heeft minder, maar veel krachtigere kernen.\n\nAchtergrond (wordt niet gevraagd): Waar wordt Harvard veel gebruikt? Microcontrollers en digitale signaalprocessors. Dat zijn toestellen die één vaste taak doen en waar het programma nooit verandert. Daar is de flexibiliteit van von Neumann niet nodig, en is de snelheid en eenvoud van Harvard een voordeel. Het programma staat dan vaak vast in een apart, niet-vluchtig geheugen." },
  { v: "Wat bepaalt dan de echte prestaties?", a: "De doorvoersnelheid van de bus, niet de rekenkracht.", o: "Het von Neumann-knelpunt",
    uitleg: "Een snellere processor kopen helpt dus niet altijd: als de bus de beperking is, staat de nieuwe processor gewoon langer te wachten. Daarom investeren fabrikanten veel in cache, snellere bussen en sneller geheugen, en niet alleen in snellere processoren." },
  { v: "Wat is bandbreedte?", a: "Hoeveel data per seconde over de bus kan.", o: "Het von Neumann-knelpunt",
    uitleg: "Uitgedrukt in bijvoorbeeld GB/s (gigabyte per seconde) of Gb/s (gigabit per seconde, let op de kleine b). Vergelijk met een snelweg: het aantal rijstroken bepaalt hoeveel auto's er per uur door kunnen. Een bredere bus of een hogere kloksnelheid van de bus geeft meer bandbreedte." },
  { v: "Hoe helpt cachegeheugen?", a: "Kleine snelle geheugens (L1, L2, L3) bij de CPU bewaren veelgebruikte data en instructies.", o: "Het von Neumann-knelpunt",
    uitleg: "Programma's gebruiken vaak dezelfde gegevens en instructies opnieuw. Door die in een klein, supersnel geheugen vlak bij de processor te bewaren, hoeft de processor niet telkens de trage weg naar het werkgeheugen te nemen. L1 is het kleinst en snelst (in de kern zelf), L3 het grootst en traagst (gedeeld door alle kernen). Details in het hoofdstuk Werkgeheugen." },
  { v: "Wat zijn gescheiden caches?", a: "Aparte caches voor instructies en data in de CPU.", o: "Het von Neumann-knelpunt",
    uitleg: "In de processor zelf worden instructies en data apart behandeld, met elk een eigen cache. Zo kan de processor tegelijk een instructie en data ophalen, althans uit de cache. Dat lijkt op de Harvard-architectuur, maar dan alleen binnenin de processor. Naar buiten toe blijft het één geheugen (von Neumann).\n\nAchtergrond (wordt niet gevraagd): 5 manieren om het knelpunt te verzachten? 1. Cachegeheugen; 2. Gescheiden caches; 3. Meer bandbreedte; 4. Vooruitlezen en voorspellen; 5. Parallelle verwerking Ezelsbruggetje 'CGBVP': Cache, Gescheiden, Bandbreedte, Vooruit, Parallel. Ze pakken het probleem op een andere manier aan: minder vaak naar het geheugen moeten (1, 2), de weg breder maken (3), de wachttijd slim opvullen (4), en het werk verdelen (5)." },
  { v: "Voorbeeld van gescheiden cache?", a: "L1 gesplitst in L1-instructies en L1-data.", o: "Het von Neumann-knelpunt",
    uitleg: "Vaak afgekort als L1i (instructies) en L1d (data). De L2- en L3-cache zijn meestal niet gesplitst: daar staan instructies en data samen. Zo combineert een moderne processor het beste van beide werelden.\n\nAchtergrond (wordt niet gevraagd): Wat is prefetching? Vooraf ophalen van data of instructies. Pre = vooraf, fetch = ophalen. Voorbeeld: als een programma een lijst getallen één voor één doorloopt, haalt de processor de volgende getallen al op terwijl hij nog met het huidige bezig is. Vergelijk met een ober die al een nieuw glas brengt als hij ziet dat het jouwe bijna leeg is.\n\nAchtergrond (wordt niet gevraagd): Wat is een microcontroller? Geef een voorbeeld. Een klein computertje in een toestel, bv. in een wasmachine of afstandsbediening. Processor, geheugen en in-/uitvoer zitten samen op één kleine, goedkope chip. Ze sturen allerlei toestellen aan: wasmachines, microgolfovens, afstandsbedieningen, speelgoed, auto's. Je hebt er thuis waarschijnlijk tientallen zonder het te weten. Een bekend voorbeeld voor hobbyisten is de Arduino." },
  { v: "Wat is branch prediction?", a: "Voorspellen welke kant het programma uitgaat.", o: "Het von Neumann-knelpunt",
    uitleg: "Een programma zit vol keuzes, zoals 'als ... dan ... anders ...'. Zo'n splitsing heet een branch (tak). Branch prediction: de processor gokt welke tak gekozen wordt en begint die al voor te bereiden, nog voor hij zeker is. Meer hierover in het hoofdstuk Processoren (ook in verband met Spectre en Meltdown).\n\nAchtergrond (wordt niet gevraagd): Wat is vooruitlezen en voorspellen? Alvast ophalen wat waarschijnlijk nodig is. De processor kijkt vooruit en haalt al data of instructies op waarvan hij verwacht dat hij ze straks nodig heeft. Als de gok juist is, ligt alles klaar wanneer het nodig is en hoeft hij niet te wachten. Is de gok fout, dan gooit hij het weg en verliest hij wat tijd. De gokken zijn vandaag meestal juist.\n\nAchtergrond (wordt niet gevraagd): Wat doet een digitale signaalprocessor (DSP)? Signalen verwerken, bv. geluid. Een DSP is gespecialiseerd in het snel en continu bewerken van signalen zoals geluid, beeld of radiogolven. Voorbeelden: ruisonderdrukking in een koptelefoon, geluidseffecten in een mengpaneel, het verwerken van gesprekken in een gsm. Omdat er voortdurend data binnenstroomt, is de snelheid van Harvard hier ideaal." },
  { v: "Het von Neumann-knelpunt (bottleneck)…\na) ontstaat doordat de processor te weinig registers heeft.\nb) ontstaat doordat instructies en data dezelfde verbinding (bus) tussen CPU en geheugen delen.\nc) wordt veroorzaakt door de traagheid van de in- en uitvoerapparaten.\nd) bestaat niet meer sinds processors meerdere cores hebben.", a: "b) Instructies en data delen dezelfde bus tussen CPU en geheugen.", o: "Het von Neumann-knelpunt",
    uitleg: "Een bewerking op data uit het geheugen betekent: de data moet naar de CPU en het resultaat moet weer terug. Alles moet over die ene verbinding, dus de grootte (bandbreedte) van de bus bepaalt mee hoe snel de computer is. d) is fout: meer cores die allemaal data nodig hebben maken het probleem eerder groter. Cache is een manier om het te verzachten.\n\nAchtergrond (wordt niet gevraagd): Hoe krijg je meer bandbreedte? Bredere bussen, sneller geheugen, meerdere geheugenkanalen. Bredere bus = meer bits tegelijk (meer rijstroken). Sneller geheugen = vaker per seconde iets versturen (hogere snelheid). Meerdere geheugenkanalen = meerdere wegen naast elkaar. In het blokschema van de slide zie je dat laatste: drie DDR3-kanalen aan de Core i7. Bij gewone pc's spreekt men van dual channel (twee kanalen).\n\nAchtergrond (wordt niet gevraagd): Wat is parallelle verwerking? Meerdere kernen of chips (zoals gpu's) verdelen het werk. Parallel = tegelijk. In plaats van één werker die alles na elkaar doet, werken meerdere werkers tegelijk aan een deel van de taak. Een processor met 8 kernen kan zo 8 dingen tegelijk doen. Dat verhelpt het knelpunt niet rechtstreeks, maar zorgt dat er minder tijd verloren gaat aan wachten.\n\nAchtergrond (wordt niet gevraagd): Hoe lost de Harvard-architectuur het knelpunt op? Aparte geheugens en bussen voor instructies en data. Instructies hebben hun eigen geheugen en hun eigen bus, data ook. Zo kunnen instructies en data tegelijk opgehaald worden en zitten ze elkaar niet in de weg. Dat is een fundamentele oplossing, geen verzachting. Nadeel: het is minder flexibel, want je kan niet zomaar extra geheugen van het ene soort voor het andere gebruiken.\n\nAchtergrond (wordt niet gevraagd): Verschil von Neumann vs Harvard? Von Neumann: 1 geheugen + 1 bus.; Harvard: aparte geheugens + bussen. Von Neumann is eenvoudiger en flexibeler, maar heeft het knelpunt. Harvard is sneller, maar complexer en minder flexibel. Moderne pc's zijn eigenlijk een mengvorm: naar buiten toe von Neumann (één werkgeheugen), maar binnenin met gescheiden L1-caches (Harvard-achtig)." },

  // ===== RISC en CISC =====
  { v: "Wat zijn RISC en CISC?", a: "Twee manieren om de instructieset van een processor te ontwerpen.", o: "RISC en CISC",
    uitleg: "Ze bepalen welke opdrachten de processor rechtstreeks begrijpt. CISC kiest voor veel krachtige, ingewikkelde instructies. RISC kiest voor weinig, eenvoudige instructies. Het is een fundamentele ontwerpkeuze die bepaalt hoe de processor gebouwd wordt, hoeveel stroom hij verbruikt en welke software erop draait." },
  { v: "Wat is een instructieset?", a: "De opdrachten die de processor rechtstreeks begrijpt.", o: "RISC en CISC",
    uitleg: "Zie het als de 'woordenschat' van de processor: de lijst van alle woorden (instructies) die hij kent. Elk programma moet uiteindelijk vertaald worden naar die woordenschat. Twee processors met een andere instructieset spreken dus een andere taal, en begrijpen elkaars programma's niet." },
  { v: "Waar staat CISC voor?", a: "Complex Instruction Set Computer.", o: "RISC en CISC",
    uitleg: "Complex = veel en krachtige instructies, waarvan sommige meerdere dingen tegelijk doen. Vertaald: computer met een complexe instructieset. Uitspraak: 'sisk'. Het bekendste voorbeeld is x86/x64 van Intel en AMD." },
  { v: "Waar staat RISC voor?", a: "Reduced Instruction Set Computer.", o: "RISC en CISC",
    uitleg: "Reduced = beperkt, vereenvoudigd. Vertaald: computer met een beperkte instructieset. Uitspraak: 'risk'. Het bekendste voorbeeld is ARM, dat in bijna alle smartphones zit." },
  { v: "Wat betekent 'reduced' in RISC?", a: "Beperkt: weinig, eenvoudige instructies.", o: "RISC en CISC",
    uitleg: "Let op: 'reduced' betekent niet 'minder krachtig'. Een RISC-processor kan perfect even snel of zelfs sneller zijn dan een CISC-processor, zoals de Apple M-chips bewijzen. De instructies zijn alleen eenvoudiger, waardoor de processor eenvoudiger, zuiniger en efficiënter kan werken." },
  { v: "Hoe zijn de instructies bij CISC?", a: "Groot en complex, vaak over meerdere klokcycli.", o: "RISC en CISC",
    uitleg: "Eén CISC-instructie kan meerdere dingen tegelijk doen, bijvoorbeeld een getal uit het geheugen halen, er iets bij optellen en het resultaat terugschrijven. Zo'n instructie heeft meerdere klokcycli nodig, en niet alle instructies duren even lang. Dat maakt de processor ingewikkelder." },
  { v: "Hoe zijn de instructies bij RISC?", a: "Klein en eenvoudig, elk in 1 klokcyclus.", o: "RISC en CISC",
    uitleg: "Elke instructie doet één klein ding: laden, optellen, opslaan, ... Omdat ze allemaal ongeveer even lang duren, kan de processor ze heel vlot na elkaar verwerken, als aan een lopende band (pipelining). De processor zelf kan daardoor eenvoudiger, kleiner en zuiniger zijn." },
  { v: "Wat is een klokcyclus?", a: "Eén tik van de processorklok.", o: "RISC en CISC",
    uitleg: "De processor werkt op het ritme van een klok die heel snel tikt. Bij elke tik zet hij een stapje verder. Een processor van 3 GHz tikt 3 miljard keer per seconde. Hoe minder tikken een instructie nodig heeft, hoe meer instructies per seconde. Meer daarover in het hoofdstuk Processoren." },
  { v: "Hoeveel klokcycli duurt een instructie bij CISC en bij RISC?", a: "CISC: vaak meerdere.\nRISC: één.", o: "RISC en CISC",
    uitleg: "Daarom staat in de tabel: CISC 'veel cycli per instructie', RISC 'weinig cycli per instructie'. Maar let op: CISC heeft wel minder instructies nodig voor dezelfde taak. Wie uiteindelijk sneller is, hangt dus af van beide factoren samen.\n\nAchtergrond (wordt niet gevraagd): Wat kan één CISC-instructie bijvoorbeeld doen? Getal uit geheugen halen, optellen en terugschrijven. Drie dingen in één instructie. Handig voor de programmeur, maar de processor moet intern toch alle drie de stappen uitvoeren. Daarom duurt zo'n instructie meerdere klokcycli." },
  { v: "Waar ligt de nadruk bij CISC?", a: "Hardware.", o: "RISC en CISC",
    uitleg: "De ingewikkelde processor doet het zware werk: hij kent veel complexe instructies en voert die zelf uit. De programmeur en de compiler hebben het daardoor makkelijker, want één instructie doet al veel. Het nadeel is dat de chip complex, groot en minder zuinig wordt." },
  { v: "Waar ligt de nadruk bij RISC?", a: "Software (de compiler).", o: "RISC en CISC",
    uitleg: "De processor blijft eenvoudig en kent alleen basisinstructies. De compiler moet slim zijn en elke taak opsplitsen in een reeks kleine stappen. Het complexe werk verschuift dus van de hardware naar de software." },
  { v: "Wat is een compiler?", a: "Programma dat broncode omzet naar processorinstructies.", o: "RISC en CISC",
    uitleg: "Broncode is wat een programmeur schrijft, in een leesbare taal zoals C, C# of Java. De processor begrijpt dat niet; hij kent alleen zijn eigen instructieset. De compiler vertaalt de broncode naar die instructies. Een compiler voor x64 maakt dus andere instructies dan een compiler voor ARM." },
  { v: "Hoe is de code bij CISC?", a: "Compact, veel cycli per instructie.", o: "RISC en CISC",
    uitleg: "Weinig instructies nodig, want elke instructie doet veel. Programma's nemen daardoor minder plaats in. Dat was vroeger een groot voordeel, toen geheugen heel duur en klein was. Maar elke instructie duurt wel langer.\n\nAchtergrond (wordt niet gevraagd): Waarom is CISC-code compact? Eén instructie doet meer werk, dus minder instructies nodig. Compact = kort, weinig plaats nodig. Vergelijk met taal: 'gisteren' is één woord, terwijl je anders 'de dag voor vandaag' moet zeggen. CISC heeft veel van zulke 'samengestelde woorden', RISC moet alles in basiswoorden uitschrijven." },
  { v: "Hoe is de code bij RISC?", a: "Groter, weinig cycli per instructie.", o: "RISC en CISC",
    uitleg: "Meer instructies nodig voor dezelfde taak, dus het programma neemt meer plaats in. Maar elke instructie is snel klaar. Vandaag is geheugen goedkoop en groot, dus de grotere code is geen echt probleem meer. Dat is een van de redenen waarom RISC populairder wordt." },
  { v: "Wat is de focus van CISC?", a: "Pure rekenkracht.", o: "RISC en CISC",
    uitleg: "Zoveel mogelijk werk verzetten, met krachtige instructies. Energieverbruik en warmte zijn minder belangrijk. Dat past bij desktops, servers en gameconsoles: die zitten aan het stopcontact en hebben ventilatoren om warmte af te voeren." },
  { v: "Wat is de focus van RISC?", a: "I/O en energieverbruik.", o: "RISC en CISC",
    uitleg: "I/O = input/output: vlot gegevens in en uit verwerken. Daarnaast is zuinig zijn heel belangrijk. Daarom zit RISC in toestellen op batterij, zoals smartphones en tablets. Minder stroom betekent een langere batterijduur en minder warmte." },
  { v: "Waarom zit RISC vaak in toestellen op batterij?", a: "RISC-processoren zijn eenvoudiger en zuiniger.", o: "RISC en CISC",
    uitleg: "Een eenvoudigere chip heeft minder transistors die stroom verbruiken. Minder stroom betekent langer met je batterij doen én minder warmte, zodat er geen ventilator nodig is. Daarom is een smartphone dun en stil, en gaat hij een hele dag mee." },
  { v: "Hoe evolueert de populariteit van CISC en RISC?", a: "CISC: dalend.\nRISC: stijgend.", o: "RISC en CISC",
    uitleg: "ARM (RISC) wint terrein in laptops (Apple MacBooks, Windows Copilot+-laptops) en in datacenters, waar energieverbruik veel geld kost. CISC (x64) blijft wel nog sterk in klassieke desktops, gameconsoles en veel servers. De verschuiving gaat geleidelijk." },
  { v: "Voorbeelden van CISC?", a: "x86/x64-processoren (Intel en AMD).", o: "RISC en CISC",
    uitleg: "Die zitten in de meeste pc's en laptops met Windows, in gameconsoles (PlayStation 5, Xbox Series X/S) en in de meeste servers. Bekende reeksen: Intel Core en AMD Ryzen." },
  { v: "Voorbeelden van RISC?", a: "ARM (mobiele toestellen, recente Apple-processoren).", o: "RISC en CISC",
    uitleg: "ARM zit in bijna alle smartphones, tablets en smartwatches, en in de Apple M-chips (Apple Silicon) van recente Macs. RISC-V is een nieuwere, open RISC-architectuur die vooral in kleine chips en onderzoek opduikt.\n\nAchtergrond (wordt niet gevraagd): Wat is RISC-V? Een RISC-architectuur, naast ARM. Extra context: RISC-V (uitspraak 'risk five') is een open standaard. Iedereen mag ze gratis gebruiken, zonder licentie te betalen zoals bij ARM. Daardoor is ze populair bij universiteiten, start-ups en voor kleine chips. Ze is nog niet zo wijdverspreid als ARM." },
  { v: "Voordeel van CISC?", a: "Kortere programma's.", o: "RISC en CISC",
    uitleg: "Omdat één instructie veel werk doet, heb je minder instructies nodig. Programma's nemen minder geheugen in, en er moeten minder instructies over de bus naar de processor, wat het von Neumann-knelpunt een beetje helpt." },
  { v: "Voordeel van RISC?", a: "Eenvoudiger, sneller per instructie, zuiniger.", o: "RISC en CISC",
    uitleg: "Een eenvoudige chip is goedkoper te maken, verbruikt minder stroom en geeft minder warmte. Omdat alle instructies ongeveer even lang duren, kan de processor ze vlot achter elkaar verwerken. Ideaal voor smartphones, laptops op batterij en datacenters." },
  { v: "Nadeel van RISC?", a: "Meer instructies nodig voor dezelfde taak.", o: "RISC en CISC",
    uitleg: "De code wordt dus groter, en de compiler moet meer werk doen. Er moeten ook meer instructies over de bus naar de processor. Vandaag weegt dat nadeel niet zwaar meer, omdat geheugen goedkoop is en cache veel opvangt.\n\nAchtergrond (wordt niet gevraagd): Hoeveel RISC-instructies voor ophalen + optellen + terugschrijven? 3: laden, optellen, opslaan. In het Engels: load, add, store. Elke instructie doet één klein ding en duurt één klokcyclus. Bij RISC mogen alleen 'load' en 'store' het geheugen aanspreken; rekenen gebeurt altijd met registers. Dat heet een load/store-architectuur (extra context)." },
  { v: "Duid per eigenschap aan of ze bij CISC of bij RISC hoort:\n• grote, complexe instructies, vaak over meerdere klokcycli\n• kleine, eenvoudige instructies, elk in 1 klokcyclus\n• nadruk op hardware\n• nadruk op software (de compiler)\n• compacte code\n• focus op I/O en energieverbruik\n• focus op pure rekenkracht\n• populariteit stijgend\n• x86/x64-processors", a: "• complexe instructies → CISC\n• eenvoudige instructies, 1 klokcyclus → RISC\n• nadruk op hardware → CISC\n• nadruk op software (compiler) → RISC\n• compacte code → CISC\n• focus op I/O en energie → RISC\n• pure rekenkracht → CISC\n• populariteit stijgend → RISC\n• x86/x64 → CISC", o: "RISC en CISC",
    uitleg: "Ezelsbruggetje: CISC = Complex, RISC = Reduced (verminderd, eenvoudig). Omdat elke RISC-instructie klein is, heb je er meer nodig: de code is groter en de compiler doet meer werk. CISC doet veel in één instructie: compacte code, maar ingewikkelde hardware. ARM is RISC.\n\nAchtergrond (wordt niet gevraagd): Waarom ligt de nadruk bij RISC op software? De compiler moet taken opsplitsen in veel kleine instructies. Wat bij CISC in één instructie in de hardware zit, moet bij RISC de compiler uitschrijven in meerdere stappen. Voorbeeld: 'tel op bij een getal in het geheugen' wordt bij RISC: laden, optellen, opslaan. De compiler beslist ook in welke volgorde die stappen het efficiëntst zijn.\n\nAchtergrond (wordt niet gevraagd): Waarom is het verschil CISC/RISC vandaag minder scherp? Moderne x86-chips vertalen complexe instructies intern naar eenvoudige stappen. Aan de buitenkant spreekt een Intel- of AMD-processor nog de CISC-taal x64, zodat alle bestaande software blijft werken. Maar binnenin knipt hij elke complexe instructie in kleine stukjes (micro-ops) en werkt hij eigenlijk RISC-achtig. Zo combineert hij compatibiliteit met snelheid." },
  { v: "Welke bewering over RISC is juist?\na) RISC-code is compacter dan CISC-code.\nb) RISC-instructies zijn klein en eenvoudig en duren elk 1 klokcyclus.\nc) RISC legt de nadruk op de hardware.\nd) x86/x64 is een RISC-architectuur.\ne) De populariteit van RISC daalt.", a: "b) RISC-instructies zijn klein en eenvoudig, elk in 1 klokcyclus.", o: "RISC en CISC",
    uitleg: "a), c) en d) zijn net de kenmerken van CISC: compacte code, nadruk op hardware, x86/x64. e) is omgekeerd: RISC (ARM) wordt steeds populairder, CISC daalt.\n\nAchtergrond (wordt niet gevraagd): Nadeel van CISC? Ingewikkelde processor, instructies duren verschillend lang. Een ingewikkelde processor heeft meer transistors nodig, verbruikt meer stroom en geeft meer warmte. Omdat instructies verschillend lang duren, is het ook moeilijker om ze vlot na elkaar te verwerken. Daarom zie je x64 niet in smartphones." },

  // ===== x86/x64 en ARM =====
  { v: "Wat is x86?", a: "De oorspronkelijke 32-bit versie (Intel/AMD).", o: "x86/x64 en ARM",
    uitleg: "x86 en x64 zijn dezelfde processorfamilie: x64 is gewoon de uitbreiding van x86. x86 was jarenlang de standaard in pc's. Het is een CISC-ontwerp met krachtige, complexe instructies." },
  { v: "Waar komt de naam x86 vandaan?", a: "Van de Intel-processoren 8086, 80286, 80386, ...", o: "x86/x64 en ARM",
    uitleg: "De Intel 8086 kwam uit in 1978. Alle opvolgers kregen een naam die op '86' eindigde, en de 'x' staat voor het wisselende cijfer ervoor. Let op: de naam heeft dus niets te maken met 86 bits! Meer over de geschiedenis in het hoofdstuk Processoren.\n\nAchtergrond (wordt niet gevraagd): Verschil bedrijfsmodel ARM vs Intel? ARM verkoopt licenties.; Intel ontwerpt én verkoopt eigen processoren. Ook AMD ontwerpt en verkoopt zijn eigen processoren. Bij x86/x64 zijn er dus maar twee grote spelers die de chips zelf maken. Bij ARM zijn er tientallen bedrijven die elk hun eigen chip maken op basis van hetzelfde ontwerp. Dat zorgt voor veel variatie en concurrentie." },
  { v: "Hoeveel werkgeheugen kan x86 max aan?", a: "Ongeveer 4 GB.", o: "x86/x64 en ARM",
    uitleg: "Daarom kon een 32-bit Windows niets doen met meer dan 4 GB RAM: zelfs als er 8 GB in de computer zat, werd de helft niet gebruikt. Dat was een van de hoofdredenen om over te schakelen naar 64 bit (x64).\n\nAchtergrond (wordt niet gevraagd): Voor hoeveel instructiesets wordt een programma gemaakt? Voor één bepaalde instructieset. De compiler vertaalt de broncode naar de instructies van één processorfamilie. Wil je hetzelfde programma op een andere processor, dan moet je het opnieuw compileren. Daarom zie je bij downloads soms keuzes zoals 'Windows x64' of 'Windows ARM64', of 'Mac Intel' en 'Mac Apple Silicon'." },
  { v: "Waarom kan x86 maar ongeveer 4 GB aan?", a: "32 bits → 2^32 bytes = 4 GB.", o: "x86/x64 en ARM",
    uitleg: "Elke plaats in het geheugen (elke byte) heeft een adres, net als elk huis in een straat een huisnummer heeft. Met 32 bits kan je 2^32 verschillende adressen maken, ongeveer 4,3 miljard. Elk adres = 1 byte, dus maximaal 4 GB. Meer huisnummers zijn er niet. Hier komt Deel I (binair tellen) terug!" },
  { v: "Hoeveel bit is x86 en hoeveel bit is x64?", a: "x86: 32 bit.\nx64: 64 bit.", o: "x86/x64 en ARM",
    uitleg: "Valkuil: de naam x86 heeft niets met 86 bits te maken; hij komt van de 8086-processor. x64 verwijst wel naar 64 bit. De bit-breedte bepaalt onder meer hoe groot de getallen zijn waarmee de processor in één keer rekent en hoeveel geheugen hij kan aanspreken." },
  { v: "Wat is x64?", a: "De 64-bit uitbreiding van x86.", o: "x86/x64 en ARM",
    uitleg: "Met 64 bits kan je 2^64 bytes aanspreken: ongeveer 16 miljard GB, veel meer dan een computer ooit zal nodig hebben. Het is een uitbreiding, geen vervanging: alle oude x86-instructies werken nog, zodat oudere software blijft draaien.\n\nAchtergrond (wordt niet gevraagd): Andere namen voor x64? x86-64 of AMD64. Ze betekenen alle drie hetzelfde. Je ziet ze bijvoorbeeld in bestandsnamen bij downloads (bv. 'setup-amd64.exe') of bij Linux-versies. Ook als je een Intel-processor hebt, is 'AMD64' de juiste versie.\n\nAchtergrond (wordt niet gevraagd): Waarom heet x64 ook AMD64? Omdat AMD de 64-bit uitbreiding ontwierp. Niet Intel dus! Intel probeerde eerst een volledig nieuwe 64-bit architectuur (Itanium), die niet compatibel was met oude software en flopte. AMD bracht rond 2003 een uitbreiding van x86 die wel alles bleef draaien. Intel heeft die uitbreiding daarna overgenomen." },
  { v: "Voordeel van x64?", a: "Veel meer werkgeheugen; nu de standaard.", o: "x86/x64 en ARM",
    uitleg: "Bijna alle pc's en laptops met Intel of AMD zijn vandaag x64. Windows 11 bestaat zelfs alleen nog in 64-bit. Naast meer geheugen kan een x64-processor ook met grotere getallen tegelijk rekenen en heeft hij meer registers." },
  { v: "Draait oudere 32-bits x86-software op een x64-computer?", a: "Ja, via compatibiliteit.", o: "x86/x64 en ARM",
    uitleg: "Compatibiliteit = de x64-processor ondersteunt nog steeds de oude x86-instructies. Daarom zie je in Windows twee mappen: 'Program Files' (64-bit programma's) en 'Program Files (x86)' (32-bit programma's). Dat is anders dan bij ARM, waar emulatie nodig is.\n\nAchtergrond (wordt niet gevraagd): Wat moet je vooral begrijpen bij x86/x64 vs ARM? Processors spreken niet dezelfde 'taal', en die taal bepaalt welke software erop draait. Dit is volgens de cursus de kernboodschap van dit deel. De 'taal' is de instructieset. Een programma dat gemaakt is voor x64 (bv. een oude Windows-game) kan een ARM-processor niet zomaar uitvoeren. Daarom is het belangrijk om te weten welke processor in welk toestel zit.\n\nAchtergrond (wordt niet gevraagd): Wat bepaalt welke software op een processor draait? De instructieset (de 'taal'). Software bestaat uiteindelijk uit instructies van één bepaalde instructieset. Een processor kan alleen instructies uitvoeren die in zijn eigen woordenschat staan. Daarom draait een Android-app (ARM) niet zomaar op een gewone Windows-pc (x64), en omgekeerd.\n\nAchtergrond (wordt niet gevraagd): Draait x64-software zomaar op ARM? Nee: aangepaste versie of emulatie nodig. En omgekeerd ook niet: ARM-software draait niet zomaar op x64. Oplossing 1: de maker brengt een aangepaste versie uit (opnieuw gecompileerd voor ARM). Oplossing 2: emulatie, waarbij software de andere processor nabootst. Dat werkt, maar is meestal trager.\n\nAchtergrond (wordt niet gevraagd): Wat is emulatie? Software die een andere processor nabootst. De emulator vertaalt de instructies van de ene processor 'live' naar instructies van de andere, zodat een programma toch kan draaien. Dat vertalen kost tijd, dus het is meestal trager. Voorbeeld: Rosetta 2 laat oude Intel-programma's draaien op Apple Silicon-Macs; Windows op ARM heeft iets gelijkaardigs." },
  { v: "x86/x64: RISC of CISC?", a: "CISC.", o: "x86/x64 en ARM",
    uitleg: "Krachtige maar complexe instructies, met de nadruk op hardware en rekenkracht. Wel met de kanttekening dat moderne x64-chips intern RISC-achtig werken, door complexe instructies op te knippen in kleine stappen." },
  { v: "ARM: RISC of CISC?", a: "RISC.", o: "x86/x64 en ARM",
    uitleg: "ARM is een volledig andere processorfamilie dan x86/x64, met een andere instructieset. De naam stond oorspronkelijk voor Acorn RISC Machine (later Advanced RISC Machines, extra context): RISC zit dus letterlijk in de naam." },
  { v: "Kenmerken van ARM?", a: "Eenvoudige instructies, zuinig, weinig warmte.", o: "x86/x64 en ARM",
    uitleg: "Die drie hangen samen: eenvoudige instructies → eenvoudigere chip met minder transistors → minder stroomverbruik → minder warmte. Daardoor is ARM ideaal voor kleine toestellen zonder ventilator en voor toestellen op batterij." },
  { v: "Waarom is ARM ideaal voor toestellen op batterij?", a: "Zuinig en weinig warmte.", o: "x86/x64 en ARM",
    uitleg: "Zuinig = de batterij gaat langer mee. Weinig warmte = geen ventilator nodig, dus het toestel kan dun en stil zijn. Daarom zitten ARM-chips in smartphones, tablets en smartwatches, en sinds kort ook in dunne laptops.\n\nAchtergrond (wordt niet gevraagd): Hoe werkt het bedrijfsmodel van ARM? ARM ontwerpt de architectuur en verkoopt licenties. ARM maakt zelf vooral geen chips. Het Britse bedrijf ontwerpt de architectuur (de instructieset en vaak ook kant-en-klare kernontwerpen) en verkoopt licenties. Andere bedrijven kopen zo'n licentie en maken er hun eigen chips mee. Daardoor bestaan er heel veel verschillende ARM-chips.\n\nAchtergrond (wordt niet gevraagd): Wat verkoopt ARM vooral? Licenties op zijn architectuur. Een licentie is een toestemming om het ontwerp te gebruiken, tegen betaling. Vaak betaalt de koper ook een klein bedrag per verkochte chip. Omdat er miljarden ARM-chips verkocht worden, levert dat ARM veel op zonder zelf fabrieken te moeten hebben.\n\nAchtergrond (wordt niet gevraagd): 3 bedrijven met ARM-chips + chipnaam? Apple (M-serie); Qualcomm (Snapdragon); Samsung (Exynos) Apple: M-chips in Macs en iPads (en A-chips in iPhones). Qualcomm: Snapdragon in veel Android-smartphones en in Windows Copilot+-laptops. Samsung: Exynos in sommige Galaxy-smartphones. Ze maken alle drie hun eigen chips op basis van een ARM-licentie." },

  // ===== Welke processor zit waar =====
  { v: "Welke architectuur zit in smartphones en wearables?", a: "Volledig ARM.", o: "Welke processor zit waar",
    uitleg: "De slide zegt: volledig gedomineerd door ARM. Dat geldt voor iPhones, Android-toestellen, smartwatches en fitnesstrackers. Er is in dit segment eigenlijk geen concurrentie van x86/x64." },
  { v: "Waarom kom je x86/x64 niet tegen in smartphones?", a: "Vanwege het hoge stroomverbruik.", o: "Welke processor zit waar",
    uitleg: "Een smartphone moet een hele dag meegaan op een kleine batterij, en heeft geen plaats voor een ventilator. Een x86/x64-processor verbruikt daarvoor te veel stroom en geeft te veel warmte. Intel heeft het geprobeerd met smartphonechips (Atom), maar is ermee gestopt." },
  { v: "Welke architectuur zit in tablets en dunne laptops?", a: "Hoofdzakelijk ARM (iPads, Android-tablets, Copilot+-laptops).", o: "Welke processor zit waar",
    uitleg: "Let op het woord 'hoofdzakelijk': niet volledig. Er is nog een kleiner deel met x86/x64. Bij dunne laptops is ARM nog relatief nieuw, maar groeit het snel dankzij een lange batterijduur en een stille werking." },
  { v: "Waar vind je bij tablets nog x86/x64?", a: "Bij specifieke instapmodellen van Windows-tablets.", o: "Welke processor zit waar",
    uitleg: "Een kleiner deel van de markt. Een voordeel van x86/x64 op een Windows-tablet is dat alle gewone Windows-programma's er zonder emulatie op draaien." },
  { v: "Wat zijn Copilot+-laptops?", a: "Recente Windows-laptops met een ARM-chip (bv. Qualcomm Snapdragon).", o: "Welke processor zit waar",
    uitleg: "Ze zijn genoemd naar Copilot, de AI-assistent van Microsoft, en hebben een speciale AI-chip (NPU) aan boord. Het was Microsofts grote stap naar ARM in Windows-laptops, vergelijkbaar met wat Apple deed met Apple Silicon. Oude x64-programma's draaien erop via emulatie." },
  { v: "Welke architectuur zit in traditionele laptops en desktops?", a: "x64 (Intel Core en AMD Ryzen).", o: "Welke processor zit waar",
    uitleg: "De slide noemt dit 'het absolute hoofdterrein van x64'. Hier is rekenkracht belangrijker dan zuinigheid, zeker bij desktops die aan het stopcontact hangen. En bijna alle Windows-software is voor x64 gemaakt." },
  { v: "Welke processorreeksen zitten in traditionele laptops en desktops?", a: "Intel Core en AMD Ryzen.", o: "Welke processor zit waar",
    uitleg: "Bij Intel: Core i3, i5, i7, i9 (en de nieuwere Core Ultra). Bij AMD: Ryzen 3, 5, 7, 9. Hoe hoger het getal, hoe krachtiger (en duurder). De Core i7 op de foto van de slide is zo'n processor." },
  { v: "Is de hardware van een traditionele laptop x86 of x64?", a: "x64.", o: "Welke processor zit waar",
    uitleg: "De fysieke hardware is x64. Oudere 32-bits x86-software draait er nog wel op, via compatibiliteit: de processor kent de oude instructies nog. Je zal vandaag geen nieuwe pc meer vinden met een echte 32-bit processor." },
  { v: "Welke uitzondering is er bij traditionele laptops en desktops?", a: "Apple MacBooks: uitsluitend ARM via Apple Silicon.", o: "Welke processor zit waar",
    uitleg: "Apple stapte van Intel over naar zijn eigen ARM-chips. Alle nieuwe Macs (MacBook, iMac, Mac mini, ...) gebruiken nu Apple Silicon. Ze bewezen dat ARM ook in laptops en desktops krachtig kan zijn, met een uitzonderlijk lange batterijduur.\n\nAchtergrond (wordt niet gevraagd): Wat is Apple Silicon en sinds wanneer? Apples eigen ARM-chips (M1, M2, ...), sinds 2020. De M1 was in 2020 de eerste. Daarvoor zaten er Intel-processoren in Macs. Apple ontwerpt de chips zelf op basis van een ARM-licentie. Oudere programma's voor Intel-Macs draaien via de emulator Rosetta 2.\n\nAchtergrond (wordt niet gevraagd): Welke draagbare console gebruikt wel ARM? De Nintendo Switch. Staat niet op de slide, maar het is logisch: een draagbare console werkt op batterij, en dan kies je voor zuinig, dus ARM. De Switch gebruikt een Nvidia Tegra-chip. Opgelet: als op het examen 'gaming consoles' staat, gaat het over PS5 en Xbox." },
  { v: "Welke architectuur zit in gaming consoles?", a: "Exclusief de x64-architectuur van AMD.", o: "Welke processor zit waar",
    uitleg: "Exclusief = enkel: geen Intel, geen ARM. AMD levert een chip waarin processor en grafische kaart samen zitten, op maat gemaakt voor elke console. Omdat consoles en pc's dezelfde architectuur hebben, kunnen game-ontwikkelaars makkelijker games voor beide maken." },
  { v: "Welke architectuur zit in enterprise servers?", a: "Gedomineerd door x64.", o: "Welke processor zit waar",
    uitleg: "Voor alle zware database- en cloud-omgevingen. Enterprise servers zijn krachtige servers van bedrijven en datacenters, waarop bijvoorbeeld websites, databanken en clouddiensten draaien. Bekende reeksen zijn Intel Xeon en AMD EPYC (extra context)." },
  { v: "Hoe evolueert ARM in datacenters?", a: "ARM wint de laatste jaren flink terrein.", o: "Welke processor zit waar",
    uitleg: "Grote cloudbedrijven ontwerpen zelfs hun eigen ARM-serverchips, zoals Amazon (Graviton) en Microsoft (Cobalt) (extra context). x64 domineert nog, maar het aandeel van ARM groeit snel." },
  { v: "Waarom wint ARM terrein in datacenters?", a: "Energiezuinig: minder stroom en koeling voor duizenden servers.", o: "Welke processor zit waar",
    uitleg: "Een datacenter heeft duizenden servers die dag en nacht draaien. Elke watt stroom kost geld, en elke watt warmte moet ook nog eens weggekoeld worden. Een klein beetje zuiniger per server bespaart samen enorm veel geld en is ook beter voor het milieu." },
  { v: "Welke processorarchitectuur (x86/x64 of ARM) vind je typisch in:\n• een smartphone\n• een PlayStation 5\n• een gaming-desktop\n• een iPad\n• een recente Apple MacBook\n• een smartwatch\n• een zware databaseserver", a: "• smartphone → ARM\n• PlayStation 5 → x64 (AMD)\n• gaming-desktop → x64\n• iPad → ARM\n• recente MacBook → ARM (Apple Silicon)\n• smartwatch → ARM\n• databaseserver → x64", o: "Welke processor zit waar",
    uitleg: "Vuistregel: werkt het op batterij en moet het zuinig zijn, dan ARM. Hangt het aan het stopcontact en telt rekenkracht, dan x64. Uitzonderingen: Apple gebruikt in MacBooks ARM (Apple Silicon), en in datacenters wint ARM terrein door zijn zuinigheid. Consoles gebruiken x64 van AMD." },
  { v: "Juist of fout? Apple MacBooks gebruiken vandaag x64-processors van Intel.", a: "FOUT", o: "Welke processor zit waar",
    uitleg: "Apple gebruikt in MacBooks uitsluitend ARM (Apple Silicon). Dat is de uitzondering bij laptops en desktops, die verder vooral x64 gebruiken." },
  { v: "Juist of fout? Moderne consoles zoals de PlayStation 5 en Xbox Series X/S gebruiken de x64-architectuur van AMD.", a: "JUIST", o: "Welke processor zit waar",
    uitleg: "Consoles hangen aan het stopcontact en hebben een ventilator, dus rekenkracht gaat voor zuinigheid, net als bij een desktop." },
  { v: "Juist of fout? In datacenters wint ARM terrein door zijn energiezuinigheid.", a: "JUIST", o: "Welke processor zit waar",
    uitleg: "Servers worden nog gedomineerd door x64 voor zware database- en cloudomgevingen, maar ARM wint de laatste jaren flink terrein omdat stroom en koeling in een datacenter veel geld kosten." },
  { v: "Juist of fout? Smartphones en wearables worden gedomineerd door x86.", a: "FOUT", o: "Welke processor zit waar",
    uitleg: "Omgekeerd: smartphones en wearables zijn volledig ARM. x86 kom je daar niet tegen door het hoge stroomverbruik." },

  // ===== Hybride ontwerp =====
  { v: "Wat is een hybride ontwerp?", a: "Snelle kernen naast tragere, maar energiezuinige kernen.", o: "Hybride ontwerp",
    uitleg: "Twee soorten kernen in één processor. Een kern (core) is een volledige verwerkingseenheid binnen de processor; een processor met 8 kernen kan 8 dingen tegelijk doen. Bij een hybride ontwerp zijn die kernen niet allemaal gelijk: sommige zijn gebouwd voor snelheid, andere voor zuinigheid." },
  { v: "Van wie komt het idee van het hybride ontwerp?", a: "Van ARM.", o: "Hybride ontwerp",
    uitleg: "Daarom staat het op de slides onder 'ARM-processoren'. ARM bedacht het rond 2011 voor smartphones (extra context), waar de batterij zo lang mogelijk moet meegaan maar het toestel toch snel moet aanvoelen." },
  { v: "Hoe heet het hybride ontwerp bij ARM?", a: "big.LITTLE.", o: "Hybride ontwerp",
    uitleg: "big = de grote, snelle kernen. LITTLE = de kleine, zuinige kernen. Let op de schrijfwijze: 'big' in kleine letters, 'LITTLE' in hoofdletters, met een puntje ertussen. De schrijfwijze zelf is een grapje: het kleine woord is groot geschreven en omgekeerd." },
  { v: "Voordeel van een hybride ontwerp?", a: "Stroom sparen bij lichte taken, kracht voor zware taken.", o: "Hybride ontwerp",
    uitleg: "Het grootste deel van de tijd doe je lichte dingen: e-mail, chatten, muziek. Daarvoor volstaan de zuinige kernen en sparen ze stroom. Start je een game of video-bewerking, dan springen de snelle kernen bij. Zo heb je het beste van twee werelden: lange batterijduur én kracht." },
  { v: "Hoe heten de kernen bij Intel?", a: "P-cores en E-cores.", o: "Hybride ontwerp",
    uitleg: "Dus niet big.LITTLE, dat is de naam bij ARM. Een processor wordt bijvoorbeeld beschreven als '6P + 8E': 6 snelle en 8 zuinige kernen, samen 14 kernen. Het besturingssysteem (Windows 11) beslist welke taak op welke soort kern draait." },
  { v: "Waar staan P-cores en E-cores voor?", a: "P = Performance (snel)\nE = Efficiency (zuinig)", o: "Hybride ontwerp",
    uitleg: "Performance-kernen zijn groot en krachtig, voor zware taken. Efficiency-kernen zijn klein en zuinig, voor lichte taken en achtergrondwerk. Ze nemen ook minder plaats in op de chip, waardoor er meer van passen." },
  { v: "Zijn de kernen bij Intel ARM-kernen?", a: "Nee, beide soorten zijn x86-kernen.", o: "Hybride ontwerp",
    uitleg: "Een veelgemaakte fout! Zowel de P-cores als de E-cores spreken de x86/x64-taal. Anders zou gewone Windows-software er niet op kunnen draaien. Intel gebruikt alleen het idee van ARM, niet de ARM-architectuur." },
  { v: "Wat nam Intel over van ARM: het idee of de architectuur?", a: "Alleen het idee.", o: "Hybride ontwerp",
    uitleg: "Het concept van snelle + zuinige kernen samen, maar uitgevoerd met eigen x86-kernen. Vergelijk het met een restaurant dat het idee van een buffet overneemt van een ander restaurant, maar wel zijn eigen gerechten serveert." },
  { v: "Op welk soort kern draait het lezen van e-mail bij voorkeur?", a: "Op een zuinige kern (E-core).", o: "Hybride ontwerp",
    uitleg: "E-mail lezen is een lichte taak: de zuinige kern kan dat perfect aan en spaart stroom. Zo gaat je laptopbatterij langer mee. Ook achtergrondtaken zoals updates of synchroniseren draaien bij voorkeur op de E-cores." },
  { v: "Op welk soort kern draait een game bij voorkeur?", a: "Op een snelle kern (P-core).", o: "Hybride ontwerp",
    uitleg: "Een game is een zware taak die veel rekenkracht nodig heeft. De P-cores zorgen dan voor de prestaties, terwijl de E-cores ondertussen de achtergrondtaken (bv. Discord, updates) overnemen, zodat de game niet gestoord wordt." },
  { v: "Bij een hybride processorontwerp (big.LITTLE)…\na) combineert men een x86-kern en een ARM-kern op één chip.\nb) combineert men snelle kernen met tragere maar energiezuinige kernen.\nc) werkt er altijd maar één kern tegelijk.\nd) gebruikt Intel ARM-kernen als E-cores.", a: "b) Snelle kernen naast tragere, energiezuinige kernen.", o: "Hybride ontwerp",
    uitleg: "Het idee komt van ARM. Intel doet het sinds Alder Lake (2021) met P-cores (performance) en E-cores (efficiency), maar beide zijn x86-kernen, geen ARM. Daarom zijn a) en d) fout. c) is fout: de kernen kunnen tegelijk werken. Lichte taken, zoals e-mail lezen, gaan naar de zuinige kernen." },
];

